      "世界保健機関（WHO）が2001年に採択した、心身機能・活動・参加という生活機能の3次元を、環境因子等との相互作用から捉える国際分類。特別支援教育でも子どもを総合的に理解する共通言語として用いられる。",
    body: "ICF（国際生活機能分類、International Classification of Functioning, Disability and Health）は、2001年5月の世界保健機関（WHO）総会で採択された、人間の生活機能と障害に関する国際的な分類です。1980年に発表された国際障害分類（ICIDH）の改訂版にあたり、約1500項目に及ぶ詳細な分類体系を持ちます。\n\nICFの最大の特徴は、心身の機能や構造の障害といったマイナス面の分類が中心であった従来の考え方から、「心身機能・身体構造」「活動」「参加」という生活機能の3つの次元を、環境因子・個人因子との相互作用の中でとらえる方向へ視点を転換した点にあります。障害を個人の内部に閉じた問題としてではなく、環境との関係の中で生じるものとして理解する枠組みといえます。\n\n特別支援教育においては、子どもの困難だけでなく強みや周囲の環境要因も含めて総合的に実態把握するための共通言語として活用されており、2007年には子どもにより即したICF-CY（児童版）もWHOから公表され、個別の教育支援計画の作成過程などで参照されることがあります。",
    relatedSlugs: ["kobetsu-shien-keikaku", "jiritsu-katsudo", "inclusive-education"],
    isCanonical: true,
    tags: ["WHO", "2001年", "生活機能"],
