    body: "特別支援学校のセンター的機能とは、特別支援学校がこれまで蓄積してきた専門的な知識や指導のノウハウを生かし、地域の幼稚園・小中学校・高等学校等における特別支援教育を積極的に支援する役割のことです。2005年（平成17年）の中央教育審議会答申「特別支援教育を推進するための制度の在り方について」において、地域の特別支援教育を推進する体制の中核を担う機関として位置づけられました。\n\n具体的な機能としては、小中学校等の教員への支援機能、特別支援教育等に関する相談・情報提供機能、障害のある子どもへの直接的な指導・支援機能、福祉・医療・労働等の関係機関との連絡・調整機能、小中学校等の教員に対する研修協力機能、施設設備等の提供機能の6つが例示されています。2007年の学校教育法改正により、こうした役割が特別支援学校の法的な役割としても明確に位置づけられました。\n\n地域の小中学校に在籍する障害のある子どもや、特別支援教育に関する専門的知識が十分でない教員を支える資源として、巡回相談などを通じて日常的に機能しています。",
