    summary:
      "障害のある子どもとない子どもが、学校間や学級間で共に活動する教育活動。相互理解を育む「交流」と教科等のねらいを達成する「共同学習」の両面を持ち、学習指導要領に計画的な実施が定められている。",
    body: "交流及び共同学習とは、特別支援学校や特別支援学級に在籍する障害のある子どもと、通常の学級に在籍する子どもが、学校行事や授業などを通じて共に活動する教育活動のことです。互いの触れ合いを通じて豊かな人間性を育む「交流」の側面と、教科等のねらいの達成を目指す「共同学習」の側面の両方を含む言葉として整理され、用いられるようになりました。\n\n学習指導要領には、特別支援学校と幼稚園・小中学校・高等学校等との間、また特別支援学級と通常の学級との間で、計画的、組織的に交流及び共同学習を行うことが規定されています。2011年に改正された障害者基本法においても、国及び地方公共団体がその推進に積極的に取り組むべきことが明記されており、文部科学省は2019年に「交流及び共同学習ガイド」を作成し実践を後押ししています。\n\n実施に当たっては、単発の行事的な交流に終わらせず、双方の子どもにとって学びのある活動となるよう、事前の打ち合わせや教員間の連携、ねらいの共有、活動後の振り返りが重要とされています。日常的な交流が難しい場合には、オンライン会議システムを用いた間接交流も広がりつつあります。",
