    body: "自閉症・情緒障害特別支援学級とは、小中学校に設置される特別支援学級の種類の一つで、自閉スペクトラム症（ASD）のある子ども、あるいは心理的な要因により選択性かん黙などの情緒の安定を欠く状態にある子どもを対象としています。少人数の学級編制のもとで、一人一人の実態に応じたきめ細かな指導が行われます。\n\n知的障害を伴わない場合も対象となる点が、知的障害特別支援学級との大きな違いです。教育課程は、各教科の指導に加えて自立活動を取り入れることができ、対人関係の形成やコミュニケーション、感覚の特性への対応、集団参加への不安の軽減などに重点を置いた指導が展開され、担当教員には発達障害に関する専門的な理解も求められます。\n\n在籍する子どもの多くは、時間割の一部について通常の学級で交流及び共同学習を行っており、教科の内容や活動の性質に応じて、在籍する学級と交流先の学級を柔軟に組み合わせながら教育課程が編成される点も特徴です。担任には特別支援教育の専門性に加え、通常の学級担任との緻密な連携調整や、保護者との丁寧な情報共有も求められます。",
