    body: "知的障害特別支援学級とは、小中学校に設置される特別支援学級のうち、知的障害のある子どもを対象とする学級です。少人数編制のもと、一人一人の発達段階や興味・関心、生活経験に応じたきめ細かな指導が行われ、日本の特別支援学級の中でも在籍する子どもの数が最も多い種別の一つとされています。\n\n教育課程の編成上の特徴として、必要に応じて小学校・中学校の各教科の目標や内容を下学年のものに替えたり、知的障害者である子どもに対する教育を行う特別支援学校の各教科（生活、国語、算数・数学など）の内容を取り入れたりすることが認められています。日常生活の指導や生活単元学習、遊びの指導、作業学習など、実生活と結び付いた具体的な学習活動が重視される点も大きな特色です。\n\n通常の学級との交流及び共同学習を計画的に行いながら、個別の指導計画・個別の教育支援計画に基づいて、卒業後の自立と社会参加を見据えた長期的な視点での指導が進められています。地域の特別支援学校が持つセンター的機能から助言を受けたり、巡回相談員と連携したりする学校も少なくありません。",
