    body: "PECS（Picture Exchange Communication System）とは、1985年にアメリカで考案された、自発的なコミュニケーションを引き出すことを目的とした絵カードを用いた支援システムです。日本語では「絵カード交換式コミュニケーションシステム」と呼ばれ、自閉スペクトラム症をはじめ言語発達に遅れのある子どもや成人を対象に、年齢を問わず世界中で用いられています。\n\n最大の特徴は、欲しい物の絵カードを相手に手渡すという「要求」から指導を始める点にあり、応用行動分析（ABA）の理論に基づいて設計されています。全6段階の指導プロセスを通じて、単一の絵カードでの要求から、複数のカードを組み合わせた文構成、質問への応答へと段階的にコミュニケーション能力を広げていきます。\n\n発語がない、あるいは少ない子どもにとって、話し言葉に先立って「伝えれば要求が叶う」という経験を積めることが大きな意義とされ、特別支援学校や療育現場で広く導入されています。",
