    body: "応用行動分析（Applied Behavior Analysis, ABA）とは、B・F・スキナーの行動理論を基盤とし、人の行動とそれを取り巻く環境との相互作用を客観的に分析することで、日常生活上の課題解決に役立てる心理学のアプローチです。行動の直前の状況（先行事象）、行動そのもの、行動の直後に起こる結果を分析するABC分析が基本的な枠組みとされています。\n\n望ましい行動の直後に称賛や好子を与えることで、その行動の生起頻度を高める「強化」の原理を活用し、生活スキルの獲得やコミュニケーション行動の促進、問題行動の軽減などを目指します。自閉スペクトラム症や知的障害、注意欠陥・多動症のある子どもへの療育・教育の分野で、エビデンスに基づく代表的な支援手法の一つとされています。\n\n特別支援教育の現場では、個別の指導計画の作成にあたって行動の背景要因（機能）を分析する視点として活用されるほか、PECSなど他の支援技法の理論的基盤としても位置づけられています。",
