    body: "早期発見・早期療育とは、発達の遅れや偏りのある子どもを乳幼児期のできるだけ早い段階で見つけ出し、専門的な療育につなげることで、その後の発達を効果的に支援しようとする考え方です。1歳6か月児健康診査や3歳児健康診査といった母子保健法に基づく乳幼児健診が、発見の重要な機会として位置づけられています。\n\n近年は、就学前の集団生活における困難が顕在化しやすい5歳児を対象とした「5歳児健診」の導入も一部自治体で進められており、就学に向けた準備期間を確保しながら支援体制を整える取組として注目されています。早期に気づくことで、保護者への相談支援や児童発達支援事業の利用など、必要な支援に早くつながることが期待されます。\n\n一方で、早期の「発見」が保護者にとって障害受容の始まりともなるため、診断や告知の伝え方には配慮が必要です。医療、保健、福祉、教育の関係機関が連携し、就学後も切れ目なく支援情報を引き継ぐ体制づくりが課題とされています。",
