    body: "場面緘黙（選択性緘黙）とは、家庭など安心できる環境では普通に話すことができるにもかかわらず、学校をはじめとする特定の社会的場面では話すことができなくなる状態を指します。DSM-5では不安症群の一つに位置づけられており、本人の意思で話さないことを選んでいるのではなく、強い不安によって声を出すことが困難になっていると理解されています。\n\n幼児期から学齢期に発症することが多く、教室で全く発言しない、うなずきや筆談でしか意思表示できないといった様子が見られます。周囲から「恥ずかしがり屋」「わがまま」と誤解されやすく、気づかれないまま長期化してしまう場合もあります。\n\n教育的支援としては、話すことを無理強いせず、うなずきやジェスチャー、筆談など話す以外の方法での参加を認めること、少人数や安心できる相手から徐々に発話の機会を広げるスモールステップの工夫が有効とされます。スクールカウンセラーや医療機関と連携し、不安を軽減する環境づくりを進めることが重要です。",
