    body: "基礎的環境整備とは、国、都道府県、市町村がそれぞれの権限と責任において、法令等に基づき教育環境の整備を進める取組を指す概念で、中央教育審議会初等中等教育分科会の報告(2012年)において「合理的配慮」と対で整理された。文部科学省はその内容として、①教育up支援体制の確立・整備、②専門性のある指導体制の確保、③個別の教育支援計画や個別の指導計画による指導、④教材の確保、⑤施設・設備の整備、⑥専門性のある教員・支援員等の人的配置、⑦個に応じた指導や学びの場の柔軟な運用、⑧交流及び共同学習の推進、という8つの観点を示している。\n\n合理的配慮は、障害のある子ども一人一人の状態や教育的ニーズに応じて学校が個別に提供する必要かつ適当な変更・調整であるのに対し、基礎的環境整備は国や自治体が制度・予算・人員配置等を通じてあらかじめ整えておく土台であるという点で性格が異なる。基礎的環境整備の水準は自治体や学校によって差があり、それが合理的配慮として提供できる内容の幅にも影響するため、両者は「基礎的環境整備の上に合理的配慮が個別に上乗せされる」関係として説明される。\n\nこの整理は、2014年の障害者権利条約批准や2016年の障害者差別解消法施行を背景に、インクルーシブ教育システムを支える公的責任の範囲を明確化するものであり、学校が合理的配慮を検討する際には、まず自校・自治体の基礎的環境整備の状況を踏まえた上で、均衡を失した過度の負担にならない範囲で個別の配慮を検討することが求められている。",
