    body: "放課後等デイサービスは、2012年の児童福祉法改正により創設された障害児通所支援で、学校教育法に規定する学校(特別支援学校を含む)に就学している障害のある児童生徒を対象に、放課後や夏休み等の長期休業中に、生活能力向上のための訓練、社会との交流の促進、創作的活動、地域交流の機会の提供等を行う通所サービスである。対象年齢は原則6歳から18歳までで、必要が認められる場合には満20歳に達するまで利用が継続できる。\n\n事業所ごとに児童発達支援管理責任者が放課後等デイサービス計画を作成し、子どもの障害特性や学校での生活状況を踏まえた個別の支援を行うとともに、保護者の就労支援やレスパイト(一時的な休息の提供)としての機能も担っている。学校や家庭とは異なる「第三の居場所」として、学習支援、運動・音楽等の活動、生活スキルの訓練、余暇活動など多様なプログラムが提供されており、事業所数・利用者数は制度創設以降大きく増加している。\n\n一方で、事業所間の支援の質のばらつきや、学習塾的な活動に偏る事業所の存在などが課題として指摘され、国は2017年に「放課後等デイサービスガイドライン」を策定し、支援の質の確保とアセスメントに基づく計画的な支援の徹底を求めている。学校との連携としては、個別の教育支援計画等を通じた情報共有が推奨されており、学校生活と放課後の支援を一貫させることが重視されている。",
