    body: "ジョブコーチ(職場適応援助者)は、障害のある人が新たに就職する際、または就職後に職場に適応する上で生じる課題に対応するため、職場に出向いて本人・事業主・家族に対して直接的かつ専門的な援助を行う専門職である。独立行政法人高齢・障害・求職者雇用支援機構(JEED)の助成金制度等に基づき、地域障害者職業センターに配置される「配置型ジョブコーチ」、社会福祉法人等に所属する「訪問型ジョブコーチ」、企業内に雇用される「企業在籍型ジョブコーチ」の3類型がある。\n\n支援内容は、障害特性を踏まえた仕事の教え方の工夫、職場内のコミュニケーション支援、通勤や生活リズムの安定に関する助言など多岐にわたる。支援は就職直後に集中的に行われた後、本人の職場適応の状況を見ながら訪問頻度を徐々に減らし、最終的には職場の上司・同僚(ナチュラルサポート)が支援の主体となるよう移行していく段階的な手法が特徴である。\n\n特別支援学校高等部の卒業生をはじめとする障害のある生徒の就労移行支援において、学校での職業教育・現場実習と、卒業後のジョブコーチ支援を接続させることで、就労の定着率を高めることが期待されている。利用に当たっては、ハローワークや障害者就業・生活支援センター、地域障害者職業センターへの相談を通じて支援計画が作成される。",
