    body: "発達障害者支援センターは、発達障害者支援法(2004年制定)第14条に基づき、都道府県及び指定都市が自ら、あるいは社会福祉法人等への委託により設置・運営する機関である。発達障害(自閉症、アスペルガー症候群その他の広汎性発達障害、学習障害、注意欠陥多動性障害等)のある本人及びその家族が、身近な地域で適切な支援を受けられるようにすることを目的とし、全国の都道府県・指定都市に設置されている。\n\n主な業務は、①相談支援(本人・家族からの生活上の相談に応じ、情報提供や助言を行う)、②発達支援(発達検査の実施や、特性に応じた療育・教育方法についての支援計画の作成・助言)、③就労支援(関係機関と連携した就労に関する相談)、④普及啓発・研修(医療・保健・福祉・教育・労働等の関係機関や地域住民への発達障害に関する理解促進、専門職向けの研修)の4本柱で構成される。運営主体の約4分の3は民間法人であり、地域の医療機関、保健所、教育委員会、児童発達支援センター等との連携拠点としての役割も担う。\n\n学校現場との関係では、特別支援教育コーディネーターや巡回相談員を介して、個々の児童生徒への支援方法についての助言を受けたり、進学・就労といったライフステージの移行に際して切れ目のない支援をつなぐ役割を果たしたりする点で重要な社会資源となっている。",
