    body: "高次脳機能障害とは、事故による頭部外傷、脳血管障害、脳炎、低酸素脳症などによって脳が損傷を受けた結果、記憶障害(新しいことを覚えられない、忘れやすい)、注意障害(注意が散漫になる、集中が続かない)、遂行機能障害(計画を立てて順序立てて物事を行うことが難しい)といった認知障害や、感情のコントロールが難しい、意欲が低下する、固執が強くなるといった社会的行動障害を主な症状とする状態を指す。外見からは分かりにくく、本人も周囲も変化に気づきにくいことから「見えにくい障害」とも呼ばれる。\n\n子どもの高次脳機能障害は、受傷や発症の時期がまだ脳の発達途上にあることから、症状の現れ方が成人とは異なり、当初は目立った症状がなくても、成長とともに新たに求められる高次な認知能力(計画性、抽象的思考、対人関係の調整など)が獲得されにくいという形で、就学後や思春期以降に学習面・行動面の困難として顕在化することがある。学校生活では、新しい学習内容が定着しにくい、指示の理解や作業の切り替えに時間がかかる、友人関係でトラブルが生じやすいといった困難が見られ、周囲から「性格の問題」や「やる気の問題」と誤解されやすい点に注意が必要である。\n\n教育的対応としては、医療機関や地域の高次脳機能障害支援拠点機関と連携した実態把握、個別の指導計画に基づく段階的な学習支援、視覚的な手掛かりやスケジュール表の活用、疲労しやすさへの配慮などが重要となる。一方で子どもは脳の可塑性が高く、長期にわたって機能が改善していく場合も多いため、継続的な経過観察と学校・家庭・医療の連携による息の長い支援が求められる。",
