    body: "ダウン症候群は、通常2本である21番染色体が3本存在すること(21トリソミー)を原因とする最も頻度の高い染色体異常の一つで、出生児のおよそ700人に1人程度の割合で見られるとされる。知的発達の遅れ、筋緊張の低下(低緊張)、特徴的な顔立ち、先天性心疾患をはじめとする合併症を伴うことが多いが、その現れ方や程度には大きな個人差があり、一人一人の発達の状態を丁寧に把握することが支援の出発点となる。\n\n乳幼児期からの療育においては、低緊張による運動発達の遅れに対する理学療法・作業療法、言語発達を促す言語聴覚療法などが行われ、児童発達支援事業所や医療機関と連携した早期支援が重視される。就学に際しては、知的障害の程度や本人・保護者の意向を踏まえ、通常の学級、通級による指導、特別支援学級、特別支援学校(知的障害)など多様な学びの場が選択肢となり、インクルーシブ教育システムの理念のもと、交流及び共同学習を通じて通常の学級の児童生徒と共に学ぶ機会を確保する取組も広がっている。\n\n学習面では、視覚的な情報処理を得意とする傾向がある一方、聴覚的な短期記憶や発音・言語表出に困難を示すことが多いとされ、視覚支援教材の活用や、スモールステップでの学習、繰り返しによる定着など、個別の指導計画に基づくきめ細かな指導が有効とされる。健康面での配慮(心疾患や頚椎の不安定性等)を要する場合もあり、学校においては主治医の意見を踏まえた運動制限や生活上の配慮を個別の教育支援計画に反映させることが重要である。",
