    body: "就学時健康診断は、学校保健安全法第11条及び同法施行令に基づき、市町村教育委員会が、翌年度の初めから小学校、義務教育学校の前期課程または特別支援学校の小学部に就学予定の子どもを対象として実施する健康診断である。実施時期は、学校保健安全法施行令により就学予定日の前年度の11月30日までと定められており、実施に当たっては市町村教育委員会が就学時健康診断票を作成し、学校医・学校歯科医等の協力を得て、内科検診、眼科検診、歯科検診、視力・聴力検査、知能や発達に関する検査、保護者との面接等を行う。\n\n就学時健康診断の目的は、入学を控えた子どもの健康状態を把握し、保健上必要な助言を行うとともに、疾病や障害の早期発見につなげ、入学後の学校生活に向けた準備を整えることにある。健康診断の結果、治療や生活規制、就学に関する指導が必要と認められる場合には、保護者に対して助言が行われるほか、心身の発達の状況等に応じて、就学先(通常の学級、通級による指導、特別支援学級、特別支援学校等)を検討するための情報の一つとしても活用される。\n\n就学先の決定に当たっては、就学時健康診断の結果に加えて、保護者や専門家の意見、本人の教育的ニーズなどを総合的に勘案し、市町村教育委員会が最終的に判断する仕組みとなっており、就学先決定に関する保護者への丁寧な情報提供と、就学相談における合意形成のプロセスが重視されている。特別な配慮を要する可能性が把握された場合には、その後の就学相談や巡回相談へと円滑に接続することが求められる。",
