    body: "特別支援学校教諭免許状は、教育職員免許法に基づき、特別支援学校において専門的な指導を行う教員に授与される免許状である。取得には、幼稚園、小学校、中学校または高等学校のいずれかの教諭普通免許状を基礎資格として保有していることが前提となり、その上で特別支援教育に関する科目の単位を大学等で修得することにより授与される。免許状は、基礎資格や修得単位数等に応じて専修免許状(大学院修士課程修了程度)、一種免許状(大学卒業程度)、二種免許状(短期大学卒業程度)の3種類に区分される。\n\n免許状は、視覚障害者、聴覚障害者、知的障害者、肢体不自由者、病弱者(身体虚弱者を含む)の5つの教育領域ごとに授与され、教員は取得した領域に応じて、当該障害種を主たる指導対象とする特別支援学校での指導に従事する。一種免許状の取得に必要な単位数は、視覚障害・聴覚障害領域がそれぞれ8単位、知的障害・肢体不自由・病弱領域がそれぞれ4単位とされており、既に免許状を保有する教員が新たに別の教育領域を追加取得することも可能である。\n\n2007年の特別支援学校制度への一本化以降、複数の障害種を教育する特別支援学校が増加する中で、教員が複数の教育領域に対応できる専門性を備えることの重要性が指摘されている。一方で、特別支援学校に在職する教員のうち、担当する障害種の免許状を保有していない、いわゆる「免許状保有率」の低さが長年の課題とされ、国は現職教員の免許取得を促進するための認定講習の拡充などに取り組んでいる。",
