      "通常の学級に在籍しながら、発音やことばの遅れ、吃音などの言語面の困難に対して通級で個別的な指導を受ける教室。一般に「ことばの教室」と呼ばれる。",
    body: "ことばの教室は、言語障害のある子どもが通常の学級に在籍したまま、週に数時間程度、特別の場で指導を受ける通級指導教室の通称です。かつての言語障害特殊学級に代わり、通級による指導の制度化に伴って整備されました。国立特別支援教育総合研究所の整理では、全国で約2,300校に設置され、通級指導教室と特別支援学級を合わせて約3万4千人が指導を受けているとされています。\n\n対象は、構音の誤り、吃音、ことばの遅れ、話し言葉のリズムや声の問題など多岐にわたります。近年は音声言語の表出・理解にとどまらず、文字の読み書きや他者とのかかわり方といったコミュニケーション全般に指導の範囲が広がっています。「ことばの遅れ」を主訴とする子どもは全国調査で約3割を占めるとされています。\n\n指導では、遊びや会話を通して発音・語彙・文のつくり方を育てるとともに、子ども自身が「話すこと」への自信を保てるよう心理面にも配慮します。在籍学級の担任や保護者との連携、在籍学級での合理的配慮（音読や発表の場面での配慮など）の調整も、ことばの教室の大切な役割です。",
    relatedSlugs: ["tsukyu", "kitsuon-shien", "kouon-shogai", "goriteki-hairyo"],
