    categories: ["special"],
    summary:
      "指先で触って読む6点の文字体系である点字を、視覚障害のある児童生徒に指導し、点字教科書などで学習を支える教育。",
    body: "点字は、縦3点・横2列の計6点の組み合わせで文字を表す触読の文字体系で、フランスのルイ・ブライユが考案した6点式が各国の言語に合わせて改良されてきました。日本の点字は、東京盲唖学校の石川倉次が仮名に対応するかたちで考案し、1890年11月1日に採用されたとされ、この日は「日本点字制定記念日」とされています。\n\n視覚障害教育では、主として点字で学ぶ児童生徒に対し、点字の読み書きを早期から丁寧に指導します。触読には手指の触覚的な識別力と系統的な練習が必要で、点字の習得は国語力や思考の土台にも関わります。教材としては、国が点字教科書を発行しているほか、点字用タイプライター、近年は点字ディスプレイや音声読み上げ機器など情報機器も併用されます。\n\n一方で、中途失明者などを中心に点字を触読できる人の割合は高くないとされる調査もあり、点字・音声・拡大文字をどう組み合わせるかは、視力や見え方、発達段階に応じて一人ひとり検討します。点字使用の児童生徒は通常の学級で学ぶ場合もあり、教科書の点訳や学習環境の整備は合理的配慮・基礎的環境整備の重要な課題です。",
