    body: "訪問教育は、障害のために通学して教育を受けることが困難な幼児児童生徒に対し、教員を家庭、児童福祉施設、医療機関などに派遣して教育を行う仕組みです。就学は可能であるものの、障害の状態が重度であったり重複していたりして、通学による教育を受けることが難しい子どもが主な対象となります。特別支援学校の教育の一形態として位置づけられています。\n\n重度・重複障害のある子どもでは、体調が日によって大きく変動することが多く、授業時数や活動内容を柔軟に調整する必要があります。障害の状態により特に必要がある場合には、各教科の目標や内容の一部を取り扱わず、自立活動を主として指導することも認められています。指導では、人や物への働きかけ、コミュニケーションの基礎、健康の維持などを丁寧に積み上げます。\n\n近年は、医療的ケアのある子どもの増加に伴い、医療・福祉との連携が一層重要になっています。感染症対策などを契機にオンライン授業を取り入れる例もあり、訪問先での対面授業とあわせて、学校行事への参加や、通学籍の児童生徒との交流など、社会とのつながりをどう保つかも課題とされています。",
