    body: "2013年8月、学校教育法施行令の一部を改正する政令（政令第244号）が公布され、障害のある子どもの就学先決定の仕組みが大きく見直されました。2012年の中央教育審議会報告を受けたもので、就学基準に該当する障害のある子どもは原則として特別支援学校に就学するとしていた従来の考え方を改め、「認定就学制度」を廃止しました。現在は、市町村教育委員会が、障害の状態、教育上必要な支援の内容、地域の教育体制の整備状況、本人・保護者・専門家の意見などを踏まえ、総合的に判断して就学先を決定します。\n\nこの判断の過程で重視されるのが、本人・保護者への十分な情報提供と意見の最大限の尊重です。教育的ニーズと必要な支援について、本人・保護者、市町村教育委員会、学校が合意形成を図ることが基本とされ、最終的な決定は市町村教育委員会が行います。\n\n助言を行う組織は、従来は「就学指導委員会」と呼ばれていましたが、早期からの教育相談や就学後の一貫した支援にも関わる組織として「教育支援委員会」（仮称）への名称・機能の見直しが提案されました。就学先は固定的なものではなく、子どもの発達や状態の変化に応じて、通常の学級、通級による指導、特別支援学級、特別支援学校の間で柔軟に見直していくことが重視されています。",
