    body: "障害者差別解消法（障害を理由とする差別の解消の推進に関する法律）は、障害者の権利に関する条約の批准に向けた国内法整備の一つとして整えられた法律で、障害の有無によって分け隔てられることなく、互いに人格と個性を尊重し合う共生社会の実現を目的としています。国・地方公共団体・民間事業者などを対象に、「不当な差別的取扱いの禁止」と「合理的配慮の提供」を求めています。\n\n2021年の改正を受け、2024年4月1日から、民間事業者による合理的配慮の提供が従来の努力義務から法的義務に変わりました。国・自治体はすでに法的義務でした。不当な差別的取扱いの禁止は事業者にも従来から法的義務であり、環境の整備は努力義務とされています。合理的配慮は、社会的障壁を取り除く対応が必要とされる場合に、過重な負担にならない範囲で行うものです。\n\n学校では、公立学校には法的義務として、私立学校には2024年4月以降は同様に法的義務として、合理的配慮の提供が求められます。配慮の内容は、障害のある本人や保護者との建設的対話を通じて決め、個別の教育支援計画などに記録して引き継ぐことが望ましいとされています。大学の入学試験における受験上の配慮などもこの法の枠組みの中で位置づけられます。",
