    body: "障害者の権利に関する条約は、2006年12月に国連総会で採択された、障害のある人の人権と基本的自由の享有を確保し、固有の尊厳の尊重を促進するための条約です。日本は2007年9月に署名し、国内法の整備を進めたうえで、2014年に批准しました。条約の整備に至る過程で、障害者基本法の改正、障害者総合支援法の制定、障害者差別解消法の制定などが行われました。\n\n教育については第24条が定めており、締約国は、障害者が教育制度一般から排除されないこと、必要な合理的配慮が提供されること、あらゆる段階でインクルーシブな教育制度と生涯学習が確保されることなどを求められています。日本ではこれを受け、中央教育審議会が2012年に報告を取りまとめ、通常の学級、通級による指導、特別支援学級、特別支援学校という連続性のある「多様な学びの場」を用意する方向が示されました。\n\nもっとも、日本の制度については、従来の分離を前提とした教育制度の枠組みを大きく変えていないという批判もあり、国連の障害者権利委員会からも、分離教育の見直しに関する勧告が議論されてきました。条約の理念と国内制度をどう結びつけるかは、インクルーシブ教育をめぐる中心的な論点です。",
