    summary:
      "2006年の学校教育法改正により、障害の種類や程度に応じた場での教育（特殊教育）から、一人ひとりの教育的ニーズに応じる特別支援教育へ転換した（2007年4月施行）。",
    body: "特殊教育は、盲学校・聾学校・養護学校、特殊学級、通級による指導など、障害の種類や程度に応じた特別な場で教育を行う仕組みでした。しかし障害の重度・重複化に加え、通常の学級に在籍するLD・ADHD・高機能自閉症などの子どもへの対応が課題となり、一人ひとりの教育的ニーズに応じて適切な支援を行う特別支援教育への転換が求められるようになりました。\n\n2006年に学校教育法が改正され、2007年4月1日に施行されました。主な内容は三つです。第一に、盲学校・聾学校・養護学校を障害種別にとらわれない「特別支援学校」に一本化し、複数の障害種を対象とできるようにしたこと。第二に、特殊学級を特別支援学級に改め、LD・ADHD・高機能自閉症などを含む発達障害を通常の学級も含むすべての学校での支援の対象として明確にしたこと。第三に、特別支援学校が地域の学校を支援する「センター的機能」を担うと定めたことです。教員免許も特別支援学校教諭免許状に改められました。\n\nこの転換により、特別支援教育は特別な場だけでなく、障害のある児童生徒が在籍するすべての学校で行うものとされました。校内委員会の設置、特別支援教育コーディネーターの指名、個別の教育支援計画の作成などの校内体制づくりも、この流れの中で進められました。",
