    body: "高等学校における通級による指導は、2016年12月の学校教育法施行規則等の改正を受け、2018年4月から制度化されました。高校でも、発達障害などで学習面・生活面に困難のある生徒が少なくないことが背景にあります。大部分の授業は通常の学級で受けながら、一部の授業について、障害に応じた特別の指導を特別な場（通級指導教室など）で受ける形態です。\n\n小・中学校との大きな違いは、単位認定と教育課程の扱いです。通級による指導は、障害に応じた特別の指導を高等学校の教育課程に加える、またはその一部（必履修教科・科目等を除く）に替えて行うことができ、修得した単位は年間7単位を超えない範囲で卒業要件の単位に含めることができます。指導内容は自立活動に相当するもので、障害による学習上または生活上の困難を主体的に改善・克服することを目的とします。\n\n制度化の初年度は、45都道府県の111教室などで実施されました。取り組みを進めるうえでは、対象生徒の把握、在籍学級や教科担任との情報共有、個別の指導計画の作成、卒業後の進路・就労を見すえた自己理解や社会的スキルの指導が重要とされます。実施校数や担当教員の専門性の確保は、今後も課題とされています。",
