    body: "療育手帳は、知的障害のある人に対して、一貫した指導・相談を行い、各種の援助措置を受けやすくするために交付される手帳です。昭和48年（1973年）の厚生事務次官通知（厚生省発児第156号）に基づいて始まった制度で、児童相談所または知的障害者更生相談所において知的障害と判定された人に対し、都道府県知事（指定都市では市長）が交付します。\n\nこの通知は技術的な助言（ガイドライン）にとどまるため、実際の運用は各都道府県・指定都市が実施要綱で定めており、判定の方法や障害の程度の区分（「A（重度）」「B（中軽度）」など）、名称、有効期間の更新の仕方は自治体ごとに異なります。そのため、転居すると区分の表記や取扱いが変わる場合があります。また、判定が知能指数に大きく依拠していることについて、国際的な知的発達症の診断基準と合致していないという研究者からの指摘もあります。\n\n手帳があると、福祉サービスの利用、税の控除や公共料金の割引、就労支援や障害者雇用の対象、特別支援学校高等部卒業後の進路選択などの場面で、支援や配慮を受けやすくなります。学校では、卒業後の福祉・就労につなぐため、在学中から保護者と手帳の取得や更新について情報共有し、移行支援に位置づけることが大切です。",
