    body: "障害者総合支援法に基づく就労系の障害福祉サービスには、就労移行支援、就労継続支援A型・B型などがあります。特別支援学校高等部の卒業後の進路としても、重要な位置を占めています。\n\n就労移行支援は、一般企業への就職をめざす障害のある人に、就労に必要な知識や能力を高める訓練を行うサービスで、利用期間は原則2年間です。必要に応じて、市町村の審査を経て延長が認められる場合があります。就労継続支援A型は、事業所と雇用契約を結んで働くもので、最低賃金が保障されます。B型は雇用契約を結ばず、作業に応じた工賃を受け取る形で、年齢制限はなく、利用期間の定めもありません。\n\n2025年10月以降は、新たにB型の利用を希望する場合、原則として「就労選択支援」を経ることが必要になりました。これは、本人の希望と能力・適性を事前に整理し、適切な働き方を選ぶための仕組みです。学校は、在学中の職場体験や作業学習、実習を通じて本人の力と希望を把握し、ジョブコーチや就労支援機関、福祉・労働・医療の関係機関と連携しながら、卒業後の生活につなぐ移行支援を進めます。",
