    body: "ニューロダイバーシティ（神経多様性）は、自閉スペクトラム症、ADHD、学習障害などにみられる脳・神経の発達の違いを、「治すべき欠陥」ではなく、人間のゲノムの自然で正常な変異として尊重する考え方です。オーストラリアの社会学者ジュディ・シンガーが1990年代末に用いたことで知られ、1998年の論文が広く紹介されています。ただし、語の起源については、ジャーナリストのハーヴェイ・ブルームや当事者のオンラインコミュニティの関与を指摘する研究もあり、単一の創始者とは言い切れないとされています。\n\nこの考え方は、障害を個人の欠陥ではなく、個人と環境との相互作用の中で生じるものと捉える社会モデルとも重なります。自閉症を、独自の文化を持つ少数者として捉え直す発想の転換を促すとも指摘されています。当事者による自己権利擁護の運動と結びつきながら広がりました。\n\n教育では、特性を「矯正」するのではなく、得意なことを生かし、学習環境や教材、評価の方法を多様な学び方に合わせて整えるという方向につながります。ユニバーサルデザイン授業や合理的配慮はその具体化の一つです。企業でも、特定分野の強みに着目して雇用を進める動きがあり、経済産業省も取り組みの理解を促しています。一方で、強い困難や支援の必要性が見えにくくなるのではないかという慎重な意見もあり、支援の必要性と多様性の尊重の両立が課題です。",
