    body: "スヌーズレンは、1970年代にオランダの重度知的障害者施設で考案された多感覚刺激を活用する支援理念である。心地よい感覚刺激が満ちた空間で過ごすことで、緊張の緩和や安心感の獲得、自己の存在への気づきを深める活動として世界各地の特別支援学校や福祉施設へと普及した。\n\n実践では、光ファイバーや心地よい音楽、アロマの心地よい香り、振動ベッドなどを備えた専用の部屋を活用する。教員は無理な課題を課さず、子どもの自発的な視線や手の動き、呼吸や表情の変化を丁寧に観察しながら、本人が好む感覚を手がかりに心地よい関わりを積み重ねる。\n\n学校現場では、重度・重複障害児の自立活動や心理的安定を促す有効な環境設定として位置づけられる。インクルーシブ教育の推進に伴い、感覚の過敏さや情緒的な混乱を抱える児童生徒が安心できる落ち着きの空間としても活用が進んでおり、個別最適な学びを支える場となっている。",
