    body: "視覚特別支援学校における歩行訓練は、視覚障害のある子どもが周囲の環境を正しく把握し、安全に移動する自立性を培う専門的指導である。第二次世界大戦後の欧米における移動訓練の知見を取り入れ、自立活動の指導として体系化されてきた歴史を持つ。\n\n指導では、白づえを身体の幅に合わせて左右に振る技術や路面の段差を探知する基本操作を身につける。また足裏の触覚や周囲の反響音、風の向きやにおいといった視覚以外の感覚を活用して自己位置を把握する空間認知や、メンタルマップの形成を段階的に促す。\n\n校内での安全確保から始まり、通学路や公共交通機関の利用へと指導の場を広げ、地域社会での自立的な移動を目指す。学校現場では、周囲の歩行者への理解啓発や点字ブロックなどのバリアフリー環境の維持と連携しながら、子どもの確かな社会参加を支えている。",
