    body: "マルチメディアDAISYは、視覚障害や発達障害、学習障害などにより通常の活字の読書に困難がある人々のために開発された国際規格のデジタル録音図書である。日本でも教科書バリアフリー法に基づき、特別な配慮を必要とする児童生徒への音声教材として広く提供されている。\n\n文字のハイライト表示と明瞭な音声読み上げが同期して再生されるため、どこを読んでいるかが一目で把握できる。文字の大きさや書体、行間、背景色、再生速度を児童生徒の特性に合わせて自由に調整でき、認知的な負荷を軽減して文章の意味理解に集中できる。\n\n通常の学級における一斉指導や家庭での予習復習において、自立的な読書と深い思考を支える手段として不可欠である。教科書を自分で読めるという体験は学習意欲と自己肯定感を大きく高め、インクルーシブ教育における公平な学びの機会を力強く支えている。",
