    body: "脊髄損傷や重症心身障害、自律神経系の機能障害などにより、発汗や血管運動による体温の自律的調節が困難な児童生徒に対する環境支援の概念である。外界の気温変化が生命や全身状態の悪化に直結するため、学校教育現場における合理的配慮として安全かつ快適な温湿度環境を組織的に維持することが求められる。\n\n教室環境の管理では、エアコンやサーキュレーターを用いた室温の均一化、遮光カーテンによる直射日光の遮断、冬場の適切な加湿などを徹底する。児童生徒の顔色、皮膚の乾燥や冷感、発汗の有無を養護教諭や介助員と連携して細かく観察し、体温測定を定時に実施する。衣服の着脱や保冷剤、温熱機器の活用による個別対応も不可欠である。\n\n通常学級でのインクルーシブ教育や校外学習への参加にあたっては、教室ごとの温度差の解消や移動時の熱中症予防策を個別の教育支援計画に明記する。非常変災時の停電に備えた蓄電池や空調代替策の確保など、危機管理を含めた環境整備が学校全体で推進されている。",
