    body: "応用行動分析の応用研究から生まれた行動改善アプローチである。自傷行為やパニック、攻撃行動などの不適切な行動を単に抑圧するのではなく、その行動が何らかの意図を他者に伝えるための機能的な手段として生じていると捉え、同じ目的を達成できる社会的に適切な伝達行動を代替として教え込む。\n\n実践にあたっては、まず機能的行動アセスメントを実施して問題行動の原因が注目、要求、回避のいずれにあるかを特定する。その上で、言葉、絵カード、身振り、支援機器による音声出力などを代替行動として設定する。児童生徒が代替行動を示した際には直ちに要求を満たし、問題行動に対しては強化を与えない対応を徹底する。\n\n意思表出が困難な子どもが不満や不安を行動問題として爆発させる前に、自ら助けを求めたり休憩を要求したりできるスキルを身につけることは、インクルーシブ教育における本質的な権利擁護である。通常学級や特別支援学級での生活の質を飛躍的に高める実践として重視されている。",
