    body: "オペラント条件づけの理論に基づき、これまで問題行動を維持させていた強化子の供給を絶つ消去手続きを導入した際、その初期段階において行動の頻度や強度、持続時間が一時的に急激に悪化する現象である。行動変容の過程で現れる典型的な反応であり、事前の予測と冷静な対応が不可欠とされる。\n\n注目を得るための大声や要求を通すためのかんしゃくに対し、指導者が一切の注目や妥協を与えずに一貫して消去を貫く。このとき、代替となる適切な表現を教え、そちらを強く強化する分化強化を並行して実施する。指導者側が一時的な激化に屈して譲歩すると、より重い問題行動が固定化するため、チーム全体での一貫した対応が厳守される。\n\n学校現場では、消去バーストに伴う自傷や周囲への危害を防ぐための安全管理と保護者との合意形成が大切である。一時的な悪化を行動改善への過渡期として科学的に理解し、教職員が動揺せず子どもを受け止め続けることが、インクルーシブな学級経営の安定をもたらす。",
