    body: "応用行動分析や教育工学に起源を持つ課題設定の基本手法である。一見すると単一に見える複雑な一連の行動や学習内容を、順序立てられた個々の小さな実行要素に細分化して分析し、学習者がどこで困難を感じているかを明確にして個別最適な指導を組み立てるために用いられる。\n\n手洗い、衣服の着脱、給食の準備などの身辺自立行動や、筆算、跳び箱などの運動・教科学習を対象として詳細なステップ表を作成する。児童生徒がどの段階まで自力で可能で、どの段階で援助が必要かをアセスメントする。つまずきのある特定の要素に絞って集中的に練習を行うことで、効率的なスキル習得を支援する。\n\n特別支援教育の個別指導計画作成の基礎であると同時に、通常の学級における授業のユニバーサルデザイン化にも大きく貢献する。ステップを可視化したチェック表を用いることで、全ての子どもが迷わず自律的に学習を進められるインクルーシブな環境が創出される。",
