    body: "応用行動分析において、課題分析によって細分化された一連の行動ステップを一つのまとまった行動系列として結びつける指導技術である。個々の小さな行動が次の行動の合図となり、最終的な行動の達成へと連鎖していく仕組みを利用して複雑なスキルの完全な習得を目指す。\n\n指導法には行動の最初のステップから順に教えていく順行連鎖化と、最後のステップのみを子どもに行わせて完了の達成感を即座に味わわせ、徐々に前の工程へと遡る逆行連鎖化がある。靴を履く、衣服を着る、道具を片付けるといった生活動作では、最後の仕上げを自力で行う逆行連鎖化が強い動機づけと高い習熟効果をもたらす。\n\n学校の自立活動や生活単元学習において、自立的な生活習慣を確立するための柱となっている。できる喜びを確実に実感させながら主体的な参加を促す支援は、子どもが自分に自信を持ち、地域や学校の共同生活へと適応していくインクルーシブ教育の土台を支えている。",
