    body: "米国のハーツとリズレイによって開発された自然主義的な言語・行動指導手法である。あらかじめ構造化された訓練室での机上練習ではなく、日常生活や自由遊びの中で子どもの内発的な興味や自発的な働きかけが生じた瞬間を捉え、その場で教育的な介入を行う手法として確立された。\n\n子どもが手の届かない場所にある玩具を取ろうとしたり、指導者に何かを要求しようとしたりした場面を活用する。指導者は本人の興味に寄り添いながら「何が欲しいの」と問いかけたり、適切な言葉のモデルを示したりして、より適切な言葉や豊かな意思表出を引き出す。本人が自発的に発声や要求を行えたら直ちに要求を満たす。\n\n訓練場面だけでなく家庭や学校の生活全般で自然に実践できるため、学んだスキルの般化が極めて容易である。特別支援学級から通常学級の休み時間まで、仲間との自然な交流の中でコミュニケーション意欲を育むインクルーシブな支援手法として幅広く活用されている。",
