    body: "クーゲル夫妻らによって開発された自閉スペクトラム症児のための自然主義的行動支援アプローチである。個別の細かな行動を一つずつ反復指導するのではなく、子どもの発達全体に波及効果を持つ中核的な領域に介入することで、多様なスキルの自発的な向上を一括して引き出すことを理念としている。\n\n中核領域として「学習への動機づけ」「自己管理」「複数刺激への応答」「自発的な社会的働きかけ」を重視する。子ども自身に教材や活動を選択させ、課題の達成そのものが直接の報酬となる自然な強化子を用いる。また、完全な正解だけでなく努力や試行そのものを積極的に肯定することで学習意欲を最大化する。\n\n学校の教室や家庭環境に溶け込みやすく、教員だけでなく保護者や同年代の仲間が支援者として機能しやすい特徴を持つ。自然な相互交渉を通じてコミュニケーション能力を伸ばすことで、インクルーシブ教育における対人関係の広がりと自律的な社会参加を力強く支える。",
