    body: "米国の生理学者ジェイコブソンが開発した心身の緊張緩和技法を、特別支援教育の現場に応用した指導法である。不安や興奮が身体の筋肉の緊張と密接に連動していることに着目し、筋肉を意図的に緊張させた後に一気に脱力させる操作を通じて、深いリフレッシュと自己調整の状態を体得させる。\n\n感覚過敏や多動性、強い不安を抱える児童生徒に対し、手、肩、顔、足などの部位ごとに「ぎゅっと力を入れて、ふわっと力を抜く」動作を順次指導する。指導者が言葉がけや手本を示しながら、緊張した状態と緩んだ状態の身体感覚の違いを明確に自覚させる。呼吸法と組み合わせることで副交感神経の働きを活性化させる。\n\n特別支援学級や通級指導の自立活動で体得した技法は、通常学級での授業前や試験前、パニックの予兆を感じた際の自己対処法として活用できる。子ども自身が身体を通じて感情をコントロールできるスキルを持つことは、インクルーシブな教室環境で安定して学び続けるための大切な合理的配慮となる。",
