    body: "現在の瞬間に生じている自身の呼吸、身体感覚、感情に対して評価や判断を下さずに意識を向ける心理学的実践を、教育や発達支援に応用したアプローチである。感情の乱れや多動、衝動性を抱える子どもに対し、自己の心身の状態に気づいて自律的にコントロールする力を高める手法として注目されている。\n\n指導では、静かに座って自分の息の流れに注意を集中する呼吸法や、鐘の音の響きを最後まで聞き届ける聴覚ワーク、身体の各部分の感覚に順番に注意を向ける活動などを短時間で行う。雑念や衝動が生じてもそれを否定せず、「今、気が散ったな」と客観的に受け止めて再び呼吸へ注意を戻す練習を重ねる。\n\n朝の会や授業の冒頭に全校・学級単位で導入することで、教室全体に落ち着いた学習規律が生まれる。感情に流されずに自分の状態を整えるスキルを育てることは、多様な困難を抱える児童生徒が安心していられるインクルーシブな学級風土づくりに大いに貢献する。",
