    body: "目標を達成するために自己の思考や行動を制御する脳の認知機能群を強化する訓練手法である。注意欠如や衝動性、学習困難を抱える児童生徒の多くがワーキングメモリや抑制機能につまずきを持つことが認知科学で明らかになり、これらの基礎的な認知機能を体系的に刺激して改善を図る実践が重視されている。\n\n訓練内容として、提示された数字や言葉を逆順に復唱する課題、複数の情報を記憶しながら別の計算を行う作業、合図に応じて行動を急制動する抑制ゲームなどを実施する。コンピュータ教材やカードゲームを活用し、学習者の実態に合わせて難易度を段階的に調整することで適切な認知的負荷をかける。\n\n認知訓練単独に頼るだけでなく、教室内での指示の簡潔化、視覚的なメモやチェックリストの提供といった環境調整と組み合わせることが不可欠である。子どもが自己の特性を理解して工夫を活用できるように支えることは、インクルーシブ教育における個別最適な学びの実現につながる。",
