    body: "CARS2（小児自閉症評定尺度）とは、ショプラーらによって開発された自閉スペクトラム症の行動評定尺度であり、世界各国で広く標準化されて利用されている。自閉症特有の行動特性を客観的・標準的に点数化し、他の知的障害や情緒障害との識別や重症度の判定を可能にするために策定された。\n\n評定は、対人関係、模倣、感情の反応、身体の使い方、物の使い方、変化への適応、視覚・聴覚などの感覚反応、コミュニケーションなど十五の行動領域にわたる。直接の行動観察や養育者からの聞き取りを統合し、定型発達児との差異の度合いに応じて採点することで、軽度から重度までの状態を判定する。\n\n教育現場においては、就学相談や特別支援学級における実態把握の指標として活用される。点数化されたプロフィールから、特定刺激への過敏性や対人不安の強さなどを詳細に読み解くことができる。子どもの行動の背景にある障害特性を教員集団が共通理解し、混乱を防ぐ環境調整や個別の合理的配慮を立案するために不可欠である。",
