    body: "PARS-TR（広汎性発達障害日本自閉症協会評定尺度改訂版）とは、日本の臨床現場や教育現場の実情に合わせて開発された自閉スペクトラム症の評定尺度である。欧米の検査を直訳するのではなく、日本の対人関係規範や集団生活の文脈に適した行動指標を用いて特性を把握するために標準化された。\n\n本尺度は、幼児期ピーク時と現在の二つの時点について、養育者への半構造化面接によって評定を行う。対人関係、コミュニケーション、こだわり、感覚過敏などの領域について具体的な行動例を基に採点し、診断の手がかりとするだけでなく、現在の生活場面で生じている困難の程度や支援ニーズを明確化する。\n\n教育現場では、短時間で実施可能な簡便さと高い信頼性から、特別支援教育コーディネーターや巡回相談員によるアセスメントで多用される。子どものこだわりや変化への不安の度合いを客観的に把握し、学校行事での配慮事項や教室内の構造化、個別の指導計画への反映を円滑に行うための有力な根拠となる。",
