    body: "就学猶予・就学免除とは、旧学校教育法等に基づき、心身に重い障害がある児童生徒について就学の義務を猶予または免除してきた歴史的制度である。戦後の教育基本法下にあっても、長年にわたり多くの障害児が教育の機会から実質的に排除され、家庭内での養育を余儀なくされていた暗い歴史を持つ。\n\n1960年代から1970年代にかけて、保護者や教職員、当事者らによる「すべての子どもに教育を」という権利保障の運動が全国で巻き起こった。裁判闘争や粘り強い立法要請の結果、1979年に養護学校（現・特別支援学校）の義務制が施行され、就学猶予・免除の制度は原則として解消に向かい、全員就学が実現した。\n\nこの歴史は、今日のインクルーシブ教育システムの原点となっている。障害の重さを理由に教育を諦めさせる時代から、障害の状態に応じた教育の場を保障する時代を経て、現在では地域の学校で共に学ぶ権利の保障へと理念が発展した。就学猶予の歴史を風化させず、差別のない教育環境を不断に更新することが求められる。",
