    body: "たんの吸引等指導者養成研修と教員の特定行為とは、社会福祉士及び介護福祉士法等の改正（2012年施行）に基づき、一定の専門研修を修了した教員が、医師の指示と看護師の指導のもとで特定の児童生徒に対して医療行為の一部を実施できる制度である。子どもの生命安全を守りつつ学習参加を保障するために整備された。\n\n対象となる特定行為は、口の中や鼻の中、気管カニューレ内部のたんの吸引、および胃ろう・腸ろう・経鼻による経管栄養である。教員は講義や筆記試験からなる基本研修と、指導看護師のもとで実際の対象児に対して行われる実地研修を完全に修了し、都道府県から認定証を受けることで初めて実施が可能となる。\n\n本制度は、看護師の急な不在時や校外学習・修学旅行など、学校生活の多様な場面における安全の重層的な確保に寄与している。教員個人の責任に帰すのではなく、校内医療的ケア運営協議会や主治医との強固なネットワークによる組織的対応が徹底されている。共生社会の実現に向け、学校現場の安心を支える制度的基盤である。",
