    body: "特別支援学校スクールバスの運行管理と安全対策とは、肢体不自由や知的障害、医療的ケアなどを必要とする児童生徒が、家庭と学校の間を安全かつ快適に通学できるように構築された総合的な安全管理システムである。広域から通学する児童生徒の命を守り、教育を受ける権利を実質的に保障する根幹事業である。\n\n具体策として、車いす固定装置の確実な点検やシートベルトの適正装着、介助員（添乗員）の複数配置による発作や体調急変への迅速な対応が挙げられる。運行会社との密接な連携、運行ルートの危険箇所点検、近年義務化された送迎バスの置き去り防止安全装置の設置と作動確認、緊急連絡網の整備などが徹底されている。\n\n地震や風水害、交通事故などの災害時を想定した避難誘導訓練や危機管理マニュアルの不断の見直しが進められている。インクルーシブ教育の進展に伴い、地域の通常校への通学支援やコミュニティバスとの連携など、多様な通学支援モデルの探求も始まっており、子どもの生命と安心を守る安全文化の維持が不可欠である。",
