    body: "特別支援学校に通う児童生徒が、居住地にある地域の小中学校等において同年代の仲間と交流する活動である。東京都などで導入されている副籍制度のように、地域の学校に学籍的な位置づけを持ちながら、地域社会の一員としての人間関係や社会性を育む理念に基づき発展してきた。\n\n実施にあたっては、学校行事や授業、給食や休み時間を共にする直接交流や、手紙やオンライン機器を活用した間接交流など多様な形態がとられる。両校の担当教員が事前に綿密な連絡協議を行い、児童生徒の実態に応じた活動内容や安全面への配慮を共有する。\n\n地域の小中学校にとっても、障害の多様性への理解を深め、共に生きる意識を培う貴重なインクルーシブ教育の契機となる。単発的な行事参加にとどまらず、日常的なつながりや放課後の地域生活へと発展させる継続的な体制づくりが求められている。",
