    body: "2007年の学校教育法改正により、従来の盲学校、ろう学校、養護学校という区分が一本化され、特別支援学校へと制度転換された。単なる学校種の再編にとどまらず、従来の特殊教育から発達障害を含む特別支援教育への全面的な移行を象徴する改革であった。\n\n制度改編に伴い、複数の障害種に対応可能な学校形態の整備が進むとともに、特別支援学校が地域の小中学校等への助言や巡回相談を担うセンター的機能が法的に位置づけられた。また、すべての学校での校内委員会の設置や担当教員の配置が義務化された。\n\nこれにより、通常の学級に在籍する軽度発達障害の児童生徒も含めた包括的な支援基盤が整えられた。インクルーシブ教育を推進する上で、専門的な知見を持つ地域の教育拠点として特別支援学校が果たす役割はますます重要性を増している。",
