    body: "ボンドとフロストによって開発された絵カード交換式コミュニケーションシステム（PECS）は、発語が難しい自閉スペクトラム症児等の自発的対話を培う技法である。応用行動分析の原理に立脚し、他者への働きかけを系統的に訓練する構成を持つ。\n\n指導は全6フェーズで進む。第1の物理的なカード手渡しから、第2の距離の拡大、第3の絵の弁別、第4の文章構成へと発展し、さらに要求応答や感想表現へと段階を引き上げる。子ども自らが他者へ自発的に要求を伝える成功体験を確実に積み重ねる。\n\n特別支援教育の現場では、言葉が出ないことによる不適応行動の改善や、自己決定の力を伸ばす手段として広く取り入れられている。教員や保護者が共通の手順で日常場面に埋め込むことで、集団生活や家庭での円滑な対話基盤が構築される。",
