    body: "アメリカのノースカロライナ州で生まれたTEACCHプログラムにおける環境調整の中核概念である。自閉スペクトラム症特有の認知特性を尊重し、空間や時間を意味づけて不安を低減させ、自立的な行動を促すための手法として世界的に普及した。\n\n構造化の5要素は、物理的構造化、視覚的スケジュール、個別ワークシステム、視覚的構造化（ルーチンや整理）、明確な手順提示から成る。どこで、いつ、何を、どれだけ行い、終わったら次は何かが一目で理解できるように教材や空間を設計する。\n\n特別支援学校や特別支援学級のみならず、通常の学級の教室環境づくりや合理的配慮としても高い効果を発揮している。見通しを持てる安心感を提供することで、過敏さによる混乱を防ぎ、子どもが主体的に学習や生活に参画できる土台を支えている。",
